PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS session_owner ON sessions(user_id);
CREATE TABLE IF NOT EXISTS journal(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,sportsbook TEXT NOT NULL,amount_cents INTEGER NOT NULL,date TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',reference TEXT,related_id TEXT,reverses_id TEXT UNIQUE,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS journal_owner ON journal(user_id,date);
CREATE UNIQUE INDEX IF NOT EXISTS journal_reference ON journal(user_id,reference) WHERE reference IS NOT NULL;
CREATE TABLE IF NOT EXISTS postings(id INTEGER PRIMARY KEY AUTOINCREMENT,journal_id TEXT NOT NULL REFERENCES journal(id) ON DELETE CASCADE,account TEXT NOT NULL,sportsbook TEXT NOT NULL,amount_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,sportsbook TEXT NOT NULL,event TEXT NOT NULL,market TEXT NOT NULL,selection TEXT NOT NULL,odds INTEGER NOT NULL,stake_cents INTEGER NOT NULL,placed_at TEXT NOT NULL,settled_at TEXT,result TEXT NOT NULL DEFAULT 'pending',payout_cents INTEGER,notes TEXT NOT NULL DEFAULT '',prediction TEXT,legs TEXT,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS bet_owner ON bets(user_id,placed_at);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,action TEXT NOT NULL,entity_id TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,monthly_limit_cents INTEGER,timezone TEXT NOT NULL DEFAULT 'UTC',notifications TEXT NOT NULL DEFAULT '{}',theme TEXT NOT NULL DEFAULT 'dark');
CREATE TABLE IF NOT EXISTS markets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at INTEGER NOT NULL);
PRAGMA user_version = 1;
